392	// UpdateUserWebhook updates an existing webhook for the user.
393	func (s *Store) UpdateUserWebhook(ctx context.Context, userID int32, webhook *storepb.WebhooksUserSetting_Webhook) error {
394		webhooks, err := s.GetUserWebhooks(ctx, userID)
395		if err != nil {
396			return err
397		}
398	
399		for i, existing := range webhooks {
400			if existing.Id == webhook.Id {
401				webhooks[i] = webhook
402				break
403			}
404		}
405	
406		_, err = s.UpsertUserSetting(ctx, &storepb.UserSetting{
407			UserId: userID,
408			Key:    storepb.UserSetting_WEBHOOKS,
409			Value: &storepb.UserSetting_Webhooks{
410				Webhooks: &storepb.WebhooksUserSetting{
411					Webhooks: webhooks,
412				},
413			},
414		})
415	
416		return err
417	}
